WITH objects AS (
SELECT 'table' AS kind,n.nspname||'.'||c.relname AS name,jsonb_build_array(c.relkind,c.relrowsecurity,c.relforcerowsecurity)::text AS definition FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname IN ('public','security') AND c.relkind IN ('r','p')
UNION ALL SELECT 'column',table_schema||'.'||table_name||'.'||column_name,jsonb_build_array(data_type,udt_schema,udt_name,is_nullable,column_default,character_maximum_length,numeric_precision,numeric_scale,is_identity,identity_generation)::text FROM information_schema.columns WHERE table_schema IN ('public','security')
UNION ALL SELECT 'constraint',n.nspname||'.'||c.relname||'.'||k.conname,pg_get_constraintdef(k.oid,true) FROM pg_constraint k JOIN pg_class c ON c.oid=k.conrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname IN ('public','security')
UNION ALL SELECT 'function',n.nspname||'.'||p.proname||'('||pg_get_function_identity_arguments(p.oid)||')',pg_get_functiondef(p.oid) FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname IN ('public','security') AND p.prokind IN ('f','p') AND NOT EXISTS (SELECT 1 FROM pg_depend d WHERE d.classid='pg_proc'::regclass AND d.objid=p.oid AND d.deptype='e')
UNION ALL SELECT 'trigger',n.nspname||'.'||c.relname||'.'||t.tgname,pg_get_triggerdef(t.oid,true)||' enabled='||t.tgenabled::text FROM pg_trigger t JOIN pg_class c ON c.oid=t.tgrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname IN ('public','security') AND NOT t.tgisinternal
UNION ALL SELECT 'policy',schemaname||'.'||tablename||'.'||policyname,jsonb_build_array(permissive,roles,cmd,qual,with_check)::text FROM pg_policies WHERE schemaname IN ('public','security') OR (schemaname='storage' AND tablename='objects')
UNION ALL SELECT 'index',schemaname||'.'||indexname,indexdef FROM pg_indexes WHERE schemaname IN ('public','security')
UNION ALL SELECT 'view',n.nspname||'.'||c.relname,jsonb_build_array(pg_get_viewdef(c.oid,true),c.reloptions)::text FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname IN ('public','security') AND c.relkind='v'
UNION ALL SELECT 'sequence',schemaname||'.'||sequencename,jsonb_build_array(data_type::text,start_value,min_value,max_value,increment_by,cycle,cache_size)::text FROM pg_sequences WHERE schemaname IN ('public','security')
UNION ALL SELECT 'grant',table_schema||'.'||table_name||'.'||grantee||'.'||privilege_type,is_grantable::text FROM information_schema.table_privileges WHERE table_schema IN ('public','security') AND grantee IN ('anon','authenticated','service_role','PUBLIC')
UNION ALL SELECT 'function_grant',n.nspname||'.'||p.proname||'('||pg_get_function_identity_arguments(p.oid)||').' || r.role,has_function_privilege(r.role,p.oid,'EXECUTE')::text FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace CROSS JOIN (VALUES ('anon'),('authenticated'),('service_role')) r(role) WHERE n.nspname IN ('public','security') AND p.prokind IN ('f','p') AND NOT EXISTS (SELECT 1 FROM pg_depend d WHERE d.classid='pg_proc'::regclass AND d.objid=p.oid AND d.deptype='e')
) SELECT kind,name,md5(regexp_replace(trim(definition),'[[:space:]]+',' ','g')) AS fingerprint FROM objects ORDER BY kind,name,fingerprint;
